-- Snapshot da PLANILHA DE ATIVOS (quem está com qual processo), usada para conciliar
-- a carga por advogado contra a tabela `processos`.
--
-- Origem: planilha de ativos do escritório (extraída em 28/08/2026) -> /tmp/ativos.json,
-- no formato [cnj_digits, advogado_curto, cnj_formatado]. Aqui ficam só os dígitos do CNJ
-- (ou o número interno, quando a planilha não trazia CNJ) + o primeiro nome da advogada.
--
-- Para que serve: com esta tabela dá para responder em SQL barato perguntas como
--   * quantos processos da planilha ainda não estão cadastrados;
--   * se algum processo está com advogada diferente da planilha (conferido: nenhum);
--   * quantos ativos no banco estão fora da planilha (processos novos desde 28/08).
--
-- Tabela sem acesso para anon/authenticated (uso interno de conciliação).
-- Reaplicar: rodar este arquivo (é idempotente — recria e repopula a tabela).

create table if not exists public.planilha_ativos (
  dig text primary key,
  adv_curto text
);
truncate public.planilha_ativos;
